import{_ as e,o as t,c as a,a4 as _}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"从刀耕火种到智慧农业 黔东南麻江县米建忠的山地耕作“三级跳”","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"从刀耕火种到智慧农业 黔东南麻江县米建忠的山地耕作“三级跳”","date":"2026-05-28T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202605/t20260522_6484386.htm","summary":"初夏的贵州省麻江县杏山街道杏山村,蓝莓基地满山翠绿,青涩果粒缀满枝头,山风裹着淡淡果香。然而倒退二十年,这片土地还是另一副模样:土质板结、水土难留,父辈们弯腰驼背刨了一辈子,也没能从黄泥里刨出个好年景。\\n改变,从一个人“换思路”开始。米建忠,这位土生土长的麻江农民,用大半辈子完成了山地耕作的“三级跳”——跳出父辈刀耕火种的旧循环,跳进特色蓝莓种植的新天地,跳上科技赋能的智慧农业快车。...\\n","contentHash":"fb4b2caff5d005f958a852d2823201f0","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-05-28-从刀耕火种到智慧农业-黔东南麻江县米建忠的山地耕作-三级跳.md","filePath":"news/2026-05-28-从刀耕火种到智慧农业-黔东南麻江县米建忠的山地耕作-三级跳.md"}'),r={name:"news/2026-05-28-从刀耕火种到智慧农业-黔东南麻江县米建忠的山地耕作-三级跳.md"};function n(s,p,o,l,d,c){return t(),a("div",null,[...p[0]||(p[0]=[_("",32)])])}const h=e(r,[["render",n]]);export{i as __pageData,h as default};
